    -- Sammel-HUD (1.6.0)
    ["Gathering HUD"] = "Sammel-HUD",
    ["What you see on screen while you ride: compass, ground lens, lap card."] = "Was du beim Reiten auf dem Bildschirm siehst: Kompass, Bodenlinse, Rundenkarte.",
    ["Show while riding"] = "Beim Reiten zeigen",
    ["Compass band"] = "Kompassband",
    ["A band at the top: the way you face, the stop you head for as a diamond and the next ones numbered, empty ones hollow. Under it the stop's name, how far, which way, and the lap so far. When Shortest Path Forever shows its own compass, the band moves under it; switch one of them off (Shortest Path's: \"Show the compass\" in its settings) if one is enough."] = "Ein Band oben: deine Blickrichtung, der nächste Wegpunkt als Raute, die folgenden nummeriert, leere hohl. Darunter Name, Entfernung, Richtung und der Stand der Runde. Zeigt Shortest Path Forever seinen eigenen Kompass, rutscht das Band darunter; schalte einen davon ab (bei Shortest Path: „Show the compass“ in seinen Einstellungen), wenn dir einer reicht.",
    ["Ground lens"] = "Bodenlinse",
    ["A tilted disc round you that turns with you: the route's line along the ground for the next few yards and the stops on it."] = "Eine gekippte Scheibe um dich, die sich mit dir dreht: die Linie der Route am Gelände für die nächsten Meter und die Wegpunkte darauf.",
    ["Lap card"] = "Rundenkarte",
    ["A card at the bottom: the stop you head for (how far, how many seconds), a dot for every stop of the lap, the lap time against your best, nodes and gold an hour."] = "Eine Karte unten: der nächste Wegpunkt (Entfernung, Sekunden), ein Punkt für jeden Wegpunkt der Runde, die Rundenzeit gegen deine Bestzeit, Vorkommen und Gold pro Stunde.",
    ["Show in combat"] = "Im Kampf zeigen",
    ["Off: the HUD steps aside while you fight."] = "Aus: Das HUD verschwindet, solange du kämpfst.",
    ["Look"] = "Aussehen",
