    ["HUD: %s. |cffffd100/gl hud compass|lens|card|r switches a part."] = "HUD: %s. |cffffd100/gl hud compass|lens|card|r schaltet ein Teil.",
    -- Linienstil (1.7.0)
    ["."] = ",",
    ["Style"] = "Stil",
    ["Solid line"] = "Linie",
    ["Dashes"] = "Striche",
    ["Dots"] = "Punkte",
    ["How routes are drawn on the world map: a solid line, dashes or dots. The width above sets how thick (dots: how big)."] = "Wie Routen auf der Weltkarte gezeichnet werden: als Linie, Striche oder Punkte. Die Breite darüber bestimmt, wie dick (bei Punkten: wie groß).",
    ["How routes are drawn on the minimap: a solid line, dashes or dots. The width above sets how thick (dots: how big)."] = "Wie Routen auf der Minimap gezeichnet werden: als Linie, Striche oder Punkte. Die Breite darüber bestimmt, wie dick (bei Punkten: wie groß).",
    -- HUD je Teil (1.7.1)
    ["Part"] = "Teil",
    ["Which part of the HUD the sliders below set. Each part keeps its own size, text size and opacity."] = "Welches Teil des HUD die Regler darunter einstellen. Jedes Teil hat eigene Größe, Schriftgröße und Deckkraft.",
    ["Text size"] = "Schriftgröße",
    ["How big the part is, all of it. While Move the parts is on, the mouse wheel over a part does the same."] = "Wie groß das ganze Teil ist. Solange „Teile verschieben“ an ist, geht das auch mit dem Mausrad über dem Teil.",
    ["How big the part's writing is, on top of its size."] = "Wie groß die Schrift im Teil ist, zusätzlich zur Größe.",
    ["How see-through the part is."] = "Wie durchsichtig das Teil ist.",
    -- Richtung je Route (1.7.2)
    ["Direction"] = "Richtung",
    ["Ride this loop the other way round."] = "Diese Runde andersherum reiten.",
    ["Ridden clockwise. Click to ride it anticlockwise: the arrows turn with it, and a ride on it carries on the new way."] = "Wird im Uhrzeigersinn geritten. Klicken, um sie gegen den Uhrzeigersinn zu reiten: Die Pfeile drehen sich mit, und eine laufende Runde geht in der neuen Richtung weiter.",
    ["Ridden anticlockwise. Click to ride it clockwise: the arrows turn with it, and a ride on it carries on the new way."] = "Wird gegen den Uhrzeigersinn geritten. Klicken, um sie im Uhrzeigersinn zu reiten: Die Pfeile drehen sich mit, und eine laufende Runde geht in der neuen Richtung weiter.",
    ["Which way each route is ridden: the round arrow on its card (clockwise or anticlockwise); click it to turn the route round."] = "In welche Richtung jede Route geritten wird, zeigt der runde Pfeil auf ihrer Karte (im oder gegen den Uhrzeigersinn). Ein Klick darauf dreht die Route um.",
    ["can't read Shortest Path Forever's walking maps (is Gatherline up to date?). Routes use straight lines until /reload."] = "kann die Laufkarten von Shortest Path Forever nicht lesen (ist Gatherline aktuell?). Bis zum /reload nutzen Routen gerade Linien.",
    ["Shortest Path Forever's walking maps can't be read"] = "Die Laufkarten von Shortest Path Forever lassen sich nicht lesen",
    -- Fertige Sperrzonen (1.8.0)
    ["Alliance town"] = "Allianz-Ort",
    ["Horde town"] = "Horde-Ort",
    ["elite, level %s"] = "Elite, Stufe %s",
    ["elite, level %s, %d spawns"] = "Elite, Stufe %s, %d Gegner",
    ["Ready-made no-go areas"] = "Fertige Sperrzonen",
    ["Ready-made areas in %s"] = "Fertige Sperrzonen in %s",
    ["(by hand)"] = "(von Hand)",
    ["(below your level)"] = "(unter deiner Stufe)",
    ["(your faction)"] = "(deine Fraktion)",
    ["Routes keep out of it. Click to let them in."] = "Routen bleiben draußen. Klicken, um sie durchzulassen.",
    ["Routes may go through it. Click to keep them out."] = "Routen dürfen hindurch. Klicken, um sie draußen zu halten.",
    ["No no-go areas of your own in %s yet. Click Draw a no-go area."] = "Noch keine eigenen Sperrzonen in %s. Klick auf Sperrzone zeichnen.",
    ["Hostile towns and elite camps, ready to use. Switch each one on or off; routes worked out from then on keep out of the ones that are on (orange on the map)."] = "Feindliche Orte und Elite-Lager, fertig zum Benutzen. Schalte jedes an oder aus; Routen, die danach berechnet werden, meiden die eingeschalteten (orange auf der Karte).",
    ["Hostile towns"] = "Feindliche Orte",
    ["The other faction's towns with a flight master (Southshore, Astranaar ...), as far as the game counts them to the town. Their guards come for you."] = "Orte der anderen Fraktion mit Flugmeister (Süderstade, Astranaar …), so weit, wie das Spiel sie zum Ort zählt. Ihre Wachen greifen dich an.",
    ["Elite camps"] = "Elite-Lager",
    ["Where elites, rare elites and bosses stand in the open world, from the Classic database. Ones far enough below your level are left open (the slider)."] = "Wo Elite-Gegner, seltene Elite und Bosse in der offenen Welt stehen, aus der Classic-Datenbank. Lager weit genug unter deiner Stufe bleiben offen (der Regler).",
    ["Elite camps open from this many levels below you"] = "Elite-Lager offen ab so vielen Stufen unter dir",
    ["An elite camp whose highest level is this many below yours or more no longer keeps routes out. As you level, camps open by themselves."] = "Ein Elite-Lager, dessen höchste Stufe so viele oder mehr unter deiner liegt, sperrt nicht mehr. Wenn du aufsteigst, öffnen sich Lager von selbst.",
    ["This zone"] = "Diese Zone",
    ["Off: none of the ready-made areas in this zone keep routes out, whatever their own switch says."] = "Aus: Keine der fertigen Sperrzonen in dieser Zone sperrt, egal was ihr eigener Schalter sagt.",
    ["Rebuild routes here"] = "Routen hier neu berechnen",
    ["Works the routes in this zone out again, to keep out of the areas as they're switched now."] = "Berechnet die Routen in dieser Zone neu, damit sie die Sperrzonen so meiden, wie sie jetzt geschaltet sind.",
    ["Automatic"] = "Automatisch",
    ["Puts every switch in this zone back to what it'd be on its own: hostile towns on, elite camps by your level."] = "Setzt jeden Schalter in dieser Zone zurück: feindliche Orte an, Elite-Lager nach deiner Stufe.",
    -- Zusammen sammeln, Nachwachsen, leer vorgefunden (1.9.0)
    ["%d%% found empty"] = "%d %% leer vorgefunden",
    ["you're not in a group. Type a player's name to send it to them."] = "du bist in keiner Gruppe. Gib einen Spielernamen ein, um sie ihm zu schicken.",
    ["sending |cffffd100%s|r to %s."] = "schicke |cffffd100%s|r an %s.",
    ["sending |cffffd100%s|r to your group."] = "schicke |cffffd100%s|r an deine Gruppe.",
    ["|cffffd100%s|r sent you the route |cff3fd0a0%s|r (%s). Add it?"] = "|cffffd100%s|r hat dir die Route |cff3fd0a0%s|r (%s) geschickt. Hinzufügen?",
    ["Add"] = "Hinzufügen",
    ["Copy this line (Ctrl+C) and send it to a friend; in Gatherline they click Import and paste it. Or send it straight to your group or a player (they need Gatherline)."] = "Diese Zeile kopieren (Strg+C) und einem Freund schicken; er klickt in Gatherline auf Importieren und fügt sie ein. Oder direkt an deine Gruppe oder einen Spieler schicken (er braucht Gatherline).",
    ["Send to my group"] = "An meine Gruppe",
    ["Send to player"] = "An Spieler",
    ["how soon nodes grew back, per zone (learnt)"] = "wie schnell Vorkommen nachgewachsen sind, pro Zone (gelernt)",
    ["regrowth seen (the smart laps use it when they've seen it 3 times):"] = "beobachtetes Nachwachsen (die schlauen Runden nutzen es ab 3 Beobachtungen):",
    ["%s (seen %d times)"] = "%s (%d-mal beobachtet)",
    ["seen %d times so far"] = "bisher %d-mal beobachtet",
    ["nothing yet: it's learnt when you or your group gather a node again."] = "noch nichts: Gatherline lernt es, wenn du oder deine Gruppe ein Vorkommen erneut abbaut.",
    ["Learn regrowth times"] = "Nachwachszeiten lernen",
    ["Gatherline notes how soon a node you (or your group) gathered was there to gather again, per zone, and skips stops no longer than that. Never longer than the minutes above. /gl regrowth shows what it has learnt."] = "Gatherline merkt sich pro Zone, wie schnell ein abgebautes Vorkommen wieder da war, und lässt Wegpunkte nicht länger aus. Nie länger als die Minuten oben. /gl regrowth zeigt, was es gelernt hat.",
    ["Gather with my group"] = "Mit meiner Gruppe sammeln",
    ["Gatherline users in your group tell each other what they gather: the laps then skip a stop your friend just picked clean too. Routes can be sent to them from Share."] = "Gatherline-Nutzer in deiner Gruppe sagen sich gegenseitig, was sie abbauen: Die Runden lassen dann auch Wegpunkte aus, die dein Freund gerade leer gemacht hat. Routen kannst du ihnen über Teilen schicken.",
    ["Each lap counts for the route's statistics; /gl stats shows them."] = "Jede Runde zählt für die Statistik der Route; /gl stats zeigt sie.",
    -- Wo lohnt es sich, Taschen, Suche umschalten (1.10.0)
    ["needs |cffffd100Auctionator|r with prices scanned at the auction house, to know what the nodes are worth."] = "braucht |cffffd100Auctionator|r mit gescannten Auktionshauspreisen, um zu wissen, was die Vorkommen wert sind.",
    ["no zone has nodes you can gather with prices Auctionator knows yet. Scan the auction house, then try again."] = "noch keine Zone hat Vorkommen, die du abbauen kannst und deren Preise Auctionator kennt. Scanne das Auktionshaus und versuch es noch mal.",
    ["where it pays (every node of a zone gathered once, at Auctionator's prices):"] = "wo es sich lohnt (alle Vorkommen einer Zone einmal abgebaut, zu Auctionator-Preisen):",
    ["%s ×%d (%s each)"] = "%s ×%d (je %s)",
    ["|cffff6040your bags are full|r – gathering won't fit any more."] = "|cffff6040deine Taschen sind voll|r – es passt nichts mehr hinein.",
    ["|cffff6040only %d bag slots free|r."] = "|cffff6040nur noch %d Taschenplätze frei|r.",
    ["bags: %d free"] = "Taschen: %d frei",
    ["Switch to the search the next stop needs"] = "Zur Suche wechseln, die der nächste Wegpunkt braucht",
    ["Tracking for the next stop"] = "Suche für den nächsten Wegpunkt",
    ["Click to switch to %s."] = "Klicken, um zu %s zu wechseln.",
    ["%s is on."] = "%s ist an.",
    ["Shows the search the stop ahead needs."] = "Zeigt die Suche, die der nächste Wegpunkt braucht.",
    ["A key for it: Key Bindings, Gatherline."] = "Eine Taste dafür: Tastaturbelegung, Gatherline.",
    ["Best gold?"] = "Wo lohnt's?",
    ["Skill up?"] = "Wo skillen?",
    ["Works out what every zone's herbs and ores you can gather are worth, at Auctionator's prices (what a node yields on average, from the Classic database), lists the best zones in chat and picks the best one here with its most valuable nodes on."] = "Rechnet aus, was die Kräuter und Erze jeder Zone wert sind, die du abbauen kannst – zu Auctionator-Preisen (was ein Vorkommen im Schnitt bringt, aus der Classic-Datenbank). Listet die besten Zonen im Chat und wählt hier die beste mit ihren wertvollsten Vorkommen aus.",
    ["Warn at free bag slots"] = "Warnen bei freien Taschenplätzen",
    ["While you ride, a warning in chat (with a sound) and on the lap card once your bags are down to this many free slots."] = "Beim Reiten eine Warnung im Chat (mit Ton) und auf der Rundenkarte, sobald nur noch so viele Taschenplätze frei sind.",
    ["Tracking button"] = "Such-Knopf",
    ["A button that shows the search the stop ahead needs (Find Herbs, Find Minerals) and lights up when it isn't on. Click it, or give it a key (Key Bindings, Gatherline), to switch. It can't change while you're in combat."] = "Ein Knopf, der die Suche zeigt, die der nächste Wegpunkt braucht (Kräutersuche, Mineraliensuche), und aufleuchtet, wenn sie nicht an ist. Klick ihn oder leg eine Taste darauf (Tastaturbelegung, Gatherline), um zu wechseln. Im Kampf ändert er sich nicht.",
